283	
284	// ------- mi_bchunk_set ---------------------------------------
285	
286	// Set a single bit
287	static inline bool mi_bchunk_set(mi_bchunk_t* chunk, size_t cidx, size_t* already_set) {
288	  mi_assert_internal(cidx < MI_BCHUNK_BITS);
289	  const size_t i = cidx / MI_BFIELD_BITS;
290	  const size_t idx = cidx % MI_BFIELD_BITS;
291	  const bool was_clear = mi_bfield_atomic_set(&chunk->bfields[i], idx);
292	  if (already_set != NULL) { *already_set = (was_clear ? 0 : 1); }
293	  return was_clear;
294	}
295	
296	// Set `0 < n <= MI_BFIELD_BITS`, and return true of the mask bits transitioned from all 0's to 1's.
297	// `already_set` contains the count of bits that were already set (used when committing ranges to account
298	// statistics correctly).
299	// Can cross over two bfields.
300	static inline bool mi_bchunk_setNX(mi_bchunk_t* chunk, size_t cidx, size_t n, size_t* already_set) {
301	  mi_assert_internal(cidx < MI_BCHUNK_BITS);
302	  mi_assert_internal(n > 0 && n <= MI_BFIELD_BITS);
303	  const size_t i = cidx / MI_BFIELD_BITS;
304	  const size_t idx = cidx % MI_BFIELD_BITS;
305	  if mi_likely(idx + n <= MI_BFIELD_BITS) {
306	    // within one field
307	    return mi_bfield_atomic_set_mask(&chunk->bfields[i], mi_bfield_mask(n,idx), already_set);
308	  }
309	  else {
310	    // spanning two fields
311	    const size_t m = MI_BFIELD_BITS - idx;  // bits to clear in the first field
312	    mi_assert_internal(m < n);
313	    mi_assert_internal(i < MI_BCHUNK_FIELDS - 1);
314	    mi_assert_internal(idx + m <= MI_BFIELD_BITS);
315	    size_t already_set1;
316	    const bool all_set1 = mi_bfield_atomic_set_mask(&chunk->bfields[i], mi_bfield_mask(m, idx), &already_set1);
317	    mi_assert_internal(n - m > 0);
318	    mi_assert_internal(n - m < MI_BFIELD_BITS);
319	    size_t already_set2;
320	    const bool all_set2 = mi_bfield_atomic_set_mask(&chunk->bfields[i+1], mi_bfield_mask(n - m, 0), &already_set2);
321	    if (already_set != NULL) { *already_set = already_set1 + already_set2; }
322	    return (all_set1 && all_set2);
323	  }
324	}
325	
326	// Set a sequence of `n` bits within a chunk.
327	// Returns true if all bits transitioned from 0 to 1 (or 1 to 0).
328	mi_decl_noinline static bool mi_bchunk_xsetNC(mi_xset_t set, mi_bchunk_t* chunk, size_t cidx, size_t n, size_t* palready_set, bool* pmaybe_all_clear) {
329	  mi_assert_internal(cidx + n <= MI_BCHUNK_BITS);
330	  mi_assert_internal(n>0);
331	  bool all_transition = true;
332	  bool maybe_all_clear = true;
333	  size_t total_already_set = 0;
334	  size_t idx   = cidx % MI_BFIELD_BITS;
335	  size_t field = cidx / MI_BFIELD_BITS;
336	  while (n > 0) {
337	    size_t m = MI_BFIELD_BITS - idx;   // m is the bits to xset in this field
338	    if (m > n) { m = n; }
339	    mi_assert_internal(idx + m <= MI_BFIELD_BITS);
340	    mi_assert_internal(field < MI_BCHUNK_FIELDS);
341	    const mi_bfield_t mask = mi_bfield_mask(m, idx);
342	    size_t already_set = 0;
343	    bool all_clear = false;
344	    const bool transition = (set ? mi_bfield_atomic_set_mask(&chunk->bfields[field], mask, &already_set)
345	                                 : mi_bfield_atomic_clear_mask(&chunk->bfields[field], mask, &all_clear));
346	    mi_assert_internal(!set || ((transition && already_set == 0) || (!transition && already_set > 0)));
347	    all_transition = all_transition && transition;
348	    total_already_set += already_set;
349	    maybe_all_clear = maybe_all_clear && all_clear;
350	    // next field
351	    field++;
352	    idx = 0;
353	    mi_assert_internal(m <= n);
354	    n -= m;
355	  }
356	  if (palready_set!=NULL) { *palready_set = total_already_set; }
357	  if (pmaybe_all_clear!=NULL) { *pmaybe_all_clear = maybe_all_clear; }
358	  return all_transition;
359	}
360	
361	static inline bool mi_bchunk_setN(mi_bchunk_t* chunk, size_t cidx, size_t n, size_t* already_set) {
362	  mi_assert_internal(n>0 && n <= MI_BCHUNK_BITS);
363	  if (n==1) return mi_bchunk_set(chunk, cidx, already_set);
364	  // if (n==8 && (cidx%8) == 0) return mi_bchunk_set8(chunk, cidx, already_set);
365	  // if (n==MI_BFIELD_BITS) return mi_bchunk_setX(chunk, cidx, already_set);
366	  if (n<=MI_BFIELD_BITS) return mi_bchunk_setNX(chunk, cidx, n, already_set);
367	  return mi_bchunk_xsetNC(MI_BIT_SET, chunk, cidx, n, already_set, NULL);
368	}
369	
370	// ------- mi_bchunk_clear ---------------------------------------
371	
372	static inline bool mi_bchunk_clear(mi_bchunk_t* chunk, size_t cidx, bool* all_clear) {
373	  mi_assert_internal(cidx < MI_BCHUNK_BITS);
374	  const size_t i = cidx / MI_BFIELD_BITS;
375	  const size_t idx = cidx % MI_BFIELD_BITS;
376	  return mi_bfield_atomic_clear(&chunk->bfields[i], idx, all_clear);
377	}
378	
379	static inline bool mi_bchunk_clearN(mi_bchunk_t* chunk, size_t cidx, size_t n, bool* maybe_all_clear) {
380	  mi_assert_internal(n>0 && n <= MI_BCHUNK_BITS);
381	  if (n==1) return mi_bchunk_clear(chunk, cidx, maybe_all_clear);
382	  // if (n==8) return mi_bchunk_clear8(chunk, cidx, maybe_all_clear);
383	  // if (n==MI_BFIELD_BITS) return mi_bchunk_clearX(chunk, cidx, maybe_all_clear);
384	  // todo: implement mi_bchunk_xsetNX instead of setNX
385	  return mi_bchunk_xsetNC(MI_BIT_CLEAR, chunk, cidx, n, NULL, maybe_all_clear);
386	}
387	
388	// Check if a sequence of `n` bits within a chunk are all set/cleared.
389	// This can cross bfield's
390	mi_decl_noinline static size_t mi_bchunk_popcountNC(mi_bchunk_t* chunk, size_t field_idx, size_t idx, size_t n) {
391	  mi_assert_internal((field_idx*MI_BFIELD_BITS) + idx + n <= MI_BCHUNK_BITS);
392	  size_t count = 0;
393	  while (n > 0) {
394	    size_t m = MI_BFIELD_BITS - idx;   // m is the bits to xset in this field
395	    if (m > n) { m = n; }
396	    mi_assert_internal(idx + m <= MI_BFIELD_BITS);
397	    mi_assert_internal(field_idx < MI_BCHUNK_FIELDS);
398	    const size_t mask = mi_bfield_mask(m, idx);
399	    count += mi_bfield_atomic_popcount_mask(&chunk->bfields[field_idx], mask);
400	    // next field
401	    field_idx++;
402	    idx = 0;
403	    n -= m;
404	  }
405	  return count;
406	}
407	
408	// Count set bits a sequence of `n` bits.
409	static inline size_t mi_bchunk_popcountN(mi_bchunk_t* chunk, size_t cidx, size_t n) {
410	  mi_assert_internal(cidx + n <= MI_BCHUNK_BITS);
411	  mi_assert_internal(n>0);
412	  if (n==0) return 0;
413	  const size_t i = cidx / MI_BFIELD_BITS;
414	  const size_t idx = cidx % MI_BFIELD_BITS;
415	  if (n==1) { return (mi_bfield_atomic_is_set(&chunk->bfields[i], idx) ? 1 : 0); }
416	  if (idx + n <= MI_BFIELD_BITS) { return mi_bfield_atomic_popcount_mask(&chunk->bfields[i], mi_bfield_mask(n, idx)); }
417	  return mi_bchunk_popcountNC(chunk, i, idx, n);
418	}
