421	// ------- mi_bchunk_is_xset ---------------------------------------
422	
423	// Check if a sequence of `n` bits within a chunk are all set/cleared.
424	// This can cross bfield's
425	mi_decl_noinline static bool mi_bchunk_is_xsetNC(mi_xset_t set, const mi_bchunk_t* chunk, size_t field_idx, size_t idx, size_t n) {
426	  mi_assert_internal((field_idx*MI_BFIELD_BITS) + idx + n <= MI_BCHUNK_BITS);
427	  while (n > 0) {
428	    size_t m = MI_BFIELD_BITS - idx;   // m is the bits to xset in this field
429	    if (m > n) { m = n; }
430	    mi_assert_internal(idx + m <= MI_BFIELD_BITS);
431	    mi_assert_internal(field_idx < MI_BCHUNK_FIELDS);
432	    const size_t mask = mi_bfield_mask(m, idx);
433	    if (!mi_bfield_atomic_is_xset_mask(set, &chunk->bfields[field_idx], mask)) {
434	      return false;
435	    }
436	    // next field
437	    field_idx++;
438	    idx = 0;
439	    n -= m;
440	  }
441	  return true;
442	}
443	
444	// Check if a sequence of `n` bits within a chunk are all set/cleared.
445	static inline bool mi_bchunk_is_xsetN(mi_xset_t set, const mi_bchunk_t* chunk, size_t cidx, size_t n) {
446	  mi_assert_internal(cidx + n <= MI_BCHUNK_BITS);
447	  mi_assert_internal(n>0);
448	  if (n==0) return true;
449	  const size_t i = cidx / MI_BFIELD_BITS;
450	  const size_t idx = cidx % MI_BFIELD_BITS;
451	  if (n==1) { return mi_bfield_atomic_is_xset(set, &chunk->bfields[i], idx); }
452	  if (idx + n <= MI_BFIELD_BITS) { return mi_bfield_atomic_is_xset_mask(set, &chunk->bfields[i], mi_bfield_mask(n, idx)); }
453	  return mi_bchunk_is_xsetNC(set, chunk, i, idx, n);
454	}
