594	static inline bool mi_bchunk_try_find_and_clear_at(mi_bchunk_t* chunk, size_t chunk_idx, size_t* pidx) {
595	  mi_assert_internal(chunk_idx < MI_BCHUNK_FIELDS);
596	  _Atomic(mi_bfield_t)* const bfield = &chunk->bfields[chunk_idx];
597	  mi_bfield_t b = mi_atomic_load_relaxed(bfield);
598	  if (b==0) return false;
599	  int tries = 0;
600	  do {  
601	    const mi_bfield_t mask = (b & (~b+1));    // == (b & -b) but avoids a compiler warning -- clear all bits except the least-significant one
602	    b = mi_atomic_and_acq_rel(bfield,~mask);  // clear the bit and set `b` to the previous value
603	    if mi_likely((b&mask)==mask) {            // if we transitioned from 1 to 0, we actually cleared it
604	      size_t bitidx = 0;
605	      mi_bfield_find_least_bit(mask,&bitidx);
606	      *pidx = (chunk_idx*MI_BFIELD_BITS) + bitidx;
607	      mi_assert_internal(*pidx < MI_BCHUNK_BITS);
608	      return true;
609	    }    
610	  } while (b!=0 && ++tries <= 4); // limit tries to reduce possible contention
611	  return false;
612	}
