614	// Find least 1-bit in a chunk and try to clear it atomically
615	// set `*pidx` to the bit index (0 <= *pidx < MI_BCHUNK_BITS) on success.
616	// This is used to find free slices and abandoned pages and should be efficient.
617	// todo: try neon version
618	static inline bool mi_bchunk_try_find_and_clear(mi_bchunk_t* chunk, size_t* pidx) {
619	  #if MI_OPT_SIMD && defined(__AVX2__) && (MI_BCHUNK_BITS==256)
620	  for(int tries=0; tries<4; tries++) {   // paranoia: at most 4 tries
621	    const __m256i vec = _mm256_load_si256((const __m256i*)chunk->bfields);
622	    const __m256i vcmp = _mm256_cmpeq_epi64(vec, mi_mm256_zero()); // (elem64 == 0 ? 0xFF  : 0)
623	    const uint32_t mask = ~_mm256_movemask_epi8(vcmp);  // mask of most significant bit of each byte (so each 8 bits are all set or clear)
624	    // mask is inverted, so each 8-bits is 0xFF iff the corresponding elem64 has a bit set (and thus can be cleared)
625	    if (mask==0) return false;
626	    mi_assert_internal((_tzcnt_u32(mask)%8) == 0); // tzcnt == 0, 8, 16, or 24
627	    const size_t chunk_idx = _tzcnt_u32(mask) / 8;
628	    if (mi_bchunk_try_find_and_clear_at(chunk, chunk_idx, pidx)) return true;
629	    // try again
630	    // note: there must be an atomic release/acquire in between or otherwise the registers may not be reloaded
631	    // we add an explicit memory barrier as older gcc compilers do not reload the registers even with an atomic acquire (issue #1206)
632	    #if defined(__GNUC__)
633	    __asm __volatile ("" : : "g"(chunk) : "memory");
634	    #endif
635	  }
636	  #elif MI_OPT_SIMD && defined(__AVX2__) && (MI_BCHUNK_BITS==512)
637	  for(int tries=0; tries<4; tries++) {   // paranoia: at most 4 tries
638	    size_t chunk_idx = 0;
639	    #if 0
640	    // one vector at a time
641	    __m256i vec = _mm256_load_si256((const __m256i*)chunk->bfields);
642	    if (mi_mm256_is_zero(vec)) {
643	      chunk_idx += 4;
644	      vec = _mm256_load_si256(((const __m256i*)chunk->bfields) + 1);
645	    }
646	    const __m256i vcmp = _mm256_cmpeq_epi64(vec, mi_mm256_zero()); // (elem64 == 0 ? 0xFF  : 0)
647	    const uint32_t mask = ~_mm256_movemask_epi8(vcmp);  // mask of most significant bit of each byte (so each 8 bits are all set or clear)
648	    // mask is inverted, so each 8-bits is 0xFF iff the corresponding elem64 has a bit set (and thus can be cleared)
649	    if (mask==0) return false;
650	    mi_assert_internal((_tzcnt_u32(mask)%8) == 0); // tzcnt == 0, 8, 16, or 24
651	    chunk_idx += _tzcnt_u32(mask) / 8;
652	    #else
653	    // a cache line is 64b so we can just as well load all at the same time
654	    const __m256i vec1  = _mm256_load_si256((const __m256i*)chunk->bfields);
655	    const __m256i vec2  = _mm256_load_si256(((const __m256i*)chunk->bfields)+1);
656	    const __m256i cmpv  = mi_mm256_zero();
657	    const __m256i vcmp1 = _mm256_cmpeq_epi64(vec1, cmpv); // (elem64 == 0 ? 0xFF  : 0)
658	    const __m256i vcmp2 = _mm256_cmpeq_epi64(vec2, cmpv); // (elem64 == 0 ? 0xFF  : 0)
659	    const uint32_t mask1 = ~_mm256_movemask_epi8(vcmp1);  // mask of most significant bit of each byte (so each 8 bits are all set or clear)
660	    const uint32_t mask2 = ~_mm256_movemask_epi8(vcmp2);  // mask of most significant bit of each byte (so each 8 bits are all set or clear)
661	    const uint64_t mask = ((uint64_t)mask2 << 32) | mask1;
662	    // mask is inverted, so each 8-bits is 0xFF iff the corresponding elem64 has a bit set (and thus can be cleared)
663	    if (mask==0) return false;
664	    mi_assert_internal((_tzcnt_u64(mask)%8) == 0); // tzcnt == 0, 8, 16, 24 , ..
665	    chunk_idx = mi_ctz(mask) / 8;
666	    #endif
667	    if (mi_bchunk_try_find_and_clear_at(chunk, chunk_idx, pidx)) return true;
668	    // try again
669	    // note: there must be an atomic release/acquire in between or otherwise the registers may not be reloaded
670	    // we add an explicit memory barrier as older gcc compilers do not reload the registers even with an atomic acquire (issue #1206)
671	    #if defined(__GNUC__)
672	    __asm __volatile ("" : : "g"(chunk) : "memory");
673	    #endif
674	  }
675	  #elif MI_OPT_SIMD && (MI_BCHUNK_BITS==512) && MI_ARCH_ARM64
676	  for(int tries=0; tries<4; tries++) {   // paranoia: at most 4 tries
677	    // a cache line is 64b so we can just as well load all at the same time (?)
678	    const uint64x2_t vzero1_lo = vceqzq_u64(vld1q_u64((uint64_t*)chunk->bfields));        // 2x64 bit is_zero
679	    const uint64x2_t vzero1_hi = vceqzq_u64(vld1q_u64((uint64_t*)chunk->bfields + 2));    // 2x64 bit is_zero
680	    const uint64x2_t vzero2_lo = vceqzq_u64(vld1q_u64((uint64_t*)chunk->bfields + 4));    // 2x64 bit is_zero
681	    const uint64x2_t vzero2_hi = vceqzq_u64(vld1q_u64((uint64_t*)chunk->bfields + 6));    // 2x64 bit is_zero
682	    const uint32x4_t vzero1    = vuzp1q_u32(vreinterpretq_u32_u64(vzero1_lo),vreinterpretq_u32_u64(vzero1_hi)); // unzip even elements: narrow to 4x32 bit is_zero ()
683	    const uint32x4_t vzero2    = vuzp1q_u32(vreinterpretq_u32_u64(vzero2_lo),vreinterpretq_u32_u64(vzero2_hi)); // unzip even elements: narrow to 4x32 bit is_zero ()
684	    const uint32x4_t vzero1x   = vreinterpretq_u32_u64(vshrq_n_u64(vreinterpretq_u64_u32(vzero1), 24));        // shift-right 2x32bit elem by 24: lo 16 bits contain the 2 lo bytes
685	    const uint32x4_t vzero2x   = vreinterpretq_u32_u64(vshrq_n_u64(vreinterpretq_u64_u32(vzero2), 24));
686	    const uint16x8_t vzero12   = vreinterpretq_u16_u32(vuzp1q_u32(vzero1x,vzero2x));                           // unzip even 32-bit elements into one vector
687	    const uint8x8_t  vzero     = vmovn_u16(vzero12);                                                           // narrow the bottom 16-bits
688	    const uint64_t mask = ~vget_lane_u64(vreinterpret_u64_u8(vzero), 0);  // 1 byte for each bfield (0xFF => bfield has a bit set)
689	    if (mask==0) return false;
690	    mi_assert_internal((mi_ctz(mask)%8) == 0); // tzcnt == 0, 8, 16, 24 , ..
691	    const size_t chunk_idx = mi_ctz(mask) / 8;
692	    if (mi_bchunk_try_find_and_clear_at(chunk, chunk_idx, pidx)) return true;
693	    // try again
694	    // note: there must be an atomic release/acquire in between or otherwise the registers may not be reloaded
695	    // we add an explicit memory barrier as older gcc compilers do not reload the registers even with an atomic acquire (issue #1206)
696	    #if defined(__GNUC__)
697	    __asm __volatile ("" : : "g"(chunk) : "memory");
698	    #endif
699	  }
700	  #else
701	  for (int i = 0; i < MI_BCHUNK_FIELDS; i++) {
702	    if (mi_bchunk_try_find_and_clear_at(chunk, i, pidx)) return true;
703	  }
704	  #endif
705	  return false;  
706	}
