713	mi_decl_maybe_unused static inline bool mi_bchunk_try_find_and_clear8_at(mi_bchunk_t* chunk, size_t chunk_idx, size_t* pidx, bool* did_temp_clear_bits) {
714	  _Atomic(mi_bfield_t)* const bfield = &chunk->bfields[chunk_idx];  
715	  mi_bfield_t b = mi_atomic_load_relaxed(bfield);
716	  if (b==0) return false;
717	  int tries = 0;
718	  do {
719	    // has_set8 has low bit in each byte set if the byte in x == 0xFF
720	    const mi_bfield_t has_set8 =  
721	      ((~b - MI_BFIELD_LO_BIT8) &     // high bit set if byte in x is 0xFF or < 0x7F
722	      (b  & MI_BFIELD_HI_BIT8))       // high bit set if byte in x is >= 0x80
723	      >> 7;                           // shift high bit to low bit
724	    size_t bitidx;
725	    if (mi_bfield_find_least_bit(has_set8, &bitidx)) { // find least 1-bit
726	      mi_assert_internal(bitidx <= (MI_BFIELD_BITS - 8));
727	      mi_assert_internal((bitidx%8)==0);
728	      if mi_likely(mi_bfield_atomic_try_clear8_optimistic(bfield,bitidx,&b,did_temp_clear_bits)) { // try to clear atomically (and update b)
729	        *pidx = (chunk_idx*MI_BFIELD_BITS) + bitidx;
730	        mi_assert_internal(*pidx + 8 <= MI_BCHUNK_BITS);
731	        return true;
732	      }
733	    }
734	    else {
735	      return false;
736	    }
737	  } while(b!=0 && ++tries <= 4); // limit tries to reduce possible contention
738	  return false;
739	}
