741	// find least aligned byte in a chunk with all bits set, and try unset it atomically
742	// set `*pidx` to its bit index (0 <= *pidx < MI_BCHUNK_BITS) on success.
743	// Used to find medium size pages in the free blocks.
744	// todo: try neon version
745	static mi_decl_noinline bool mi_bchunk_try_find_and_clear8(mi_bchunk_t* chunk, size_t* pidx, bool* did_temp_clear_bits) {
746	  #if MI_OPT_SIMD && defined(__AVX2__) && (MI_BCHUNK_BITS==512)
747	  for(int tries=0; tries<4; tries++) {   // paranoia: at most 4 tries
748	    // since a cache-line is 64b, load all at once
749	    const __m256i vec1 = _mm256_load_si256((const __m256i*)chunk->bfields);
750	    const __m256i vec2 = _mm256_load_si256((const __m256i*)chunk->bfields+1);
751	    const __m256i cmpv = mi_mm256_ones();
752	    const __m256i vcmp1 = _mm256_cmpeq_epi8(vec1, cmpv); // (byte == ~0 ? 0xFF : 0)
753	    const __m256i vcmp2 = _mm256_cmpeq_epi8(vec2, cmpv); // (byte == ~0 ? 0xFF : 0)
754	    const uint32_t mask1 = _mm256_movemask_epi8(vcmp1);    // mask of most significant bit of each byte
755	    const uint32_t mask2 = _mm256_movemask_epi8(vcmp2);    // mask of most significant bit of each byte
756	    const uint64_t mask = ((uint64_t)mask2 << 32) | mask1;
757	    // mask is inverted, so each bit is 0xFF iff the corresponding byte has a bit set (and thus can be cleared)
758	    if (mask==0) return false;
759	    const size_t bidx = _tzcnt_u64(mask);          // byte-idx of the byte in the chunk
760	    const size_t chunk_idx = bidx / 8;
761	    const size_t idx = (bidx % 8)*8;
762	    mi_assert_internal(chunk_idx < MI_BCHUNK_FIELDS);
763	    if mi_likely(mi_bfield_atomic_try_clear8_optimistic(&chunk->bfields[chunk_idx], idx, NULL, did_temp_clear_bits)) {  // clear it atomically
764	      *pidx = (chunk_idx*MI_BFIELD_BITS) + idx;
765	      mi_assert_internal(*pidx + 8 <= MI_BCHUNK_BITS);
766	      return true;
767	    }
768	    // try again
769	    // note: there must be an atomic release/acquire in between or otherwise the registers may not be reloaded
770	    // we add an explicit memory barrier as older gcc compilers do not reload the registers even with an atomic acquire (issue #1206)
771	    #if defined(__GNUC__)
772	    __asm __volatile ("" : : "g"(chunk) : "memory");
773	    #endif
774	  }
775	  #else
776	    for (int i = 0; i < MI_BCHUNK_FIELDS; i++) {
777	      if (mi_bchunk_try_find_and_clear8_at(chunk, i, pidx, did_temp_clear_bits)) return true;
778	    }
779	  #endif
780	  return false;
781	}
