789	// find a sequence of `n` bits in a chunk with `0 < n <= MI_BFIELD_BITS` with all bits set,
790	// and try to clear them atomically.
791	// set `*pidx` to its bit index (0 <= *pidx <= MI_BCHUNK_BITS - n) on success.
792	// will cross bfield boundaries.
793	mi_decl_noinline static bool mi_bchunk_try_find_and_clearNX(mi_bchunk_t* chunk, size_t n, size_t* pidx, bool* did_temp_clear_bits) {
794	  if (n == 0 || n > MI_BFIELD_BITS) return false;
795	  const mi_bfield_t mask = mi_bfield_mask(n, 0);
796	  // for all fields in the chunk
797	  for (int i = 0; i < MI_BCHUNK_FIELDS; i++) {
798	    mi_bfield_t b0 = mi_atomic_load_relaxed(&chunk->bfields[i]);
799	    mi_bfield_t b = b0;
800	    size_t idx;
801	
802	    // is there a range inside the field?
803	    while (mi_bfield_find_least_bit(b, &idx)) { // find least 1-bit
804	      if (idx + n > MI_BFIELD_BITS) break; // too short: maybe cross over, or continue with the next field
805	
806	      const size_t bmask = mask<<idx;
807	      mi_assert_internal(bmask>>idx == mask);
808	      if ((b&bmask) == bmask) { // found a match with all bits set, try clearing atomically
809	        if mi_likely(mi_bfield_atomic_try_clear_mask_optimistic(&chunk->bfields[i], bmask, &b0, did_temp_clear_bits)) {  // updates b0 with the previous value        
810	          *pidx = (i*MI_BFIELD_BITS) + idx;
811	          mi_assert_internal(*pidx < MI_BCHUNK_BITS);
812	          mi_assert_internal(*pidx + n <= MI_BCHUNK_BITS);
813	          return true;
814	        }
815	        else {
816	          // if we failed to atomically commit, reload b and try again from the start
817	          b = b0; // = mi_atomic_load_acquire(&chunk->bfields[i]);
818	        }
819	      }
820	      else {
821	        // advance by clearing the least run of ones, for example, with n>=4, idx=2:
822	        // b             = 1111 1101 1010 1100
823	        // .. + (1<<idx) = 1111 1101 1011 0000
824	        // .. & b        = 1111 1101 1010 0000
825	        b = b & (b + (mi_bfield_one() << idx));
826	      }
827	    }
828	
829	    // check if we can cross into the next bfield
830	    if (b!=0 && i < MI_BCHUNK_FIELDS-1) {
831	      const size_t post = mi_bfield_clz(~b);
832	      if (post > 0) {
833	        const size_t pre = mi_bfield_ctz(~mi_atomic_load_relaxed(&chunk->bfields[i+1]));
834	        if (post + pre >= n) {
835	          // it fits -- try to claim it atomically
836	          const size_t cidx = (i*MI_BFIELD_BITS) + (MI_BFIELD_BITS - post);
837	          if (mi_bchunk_try_clearNX(chunk, cidx, n, NULL, did_temp_clear_bits)) {
838	            // we cleared all atomically
839	            *pidx = cidx;
840	            mi_assert_internal(*pidx < MI_BCHUNK_BITS);
841	            mi_assert_internal(*pidx + n <= MI_BCHUNK_BITS);
842	            return true;
843	          }
844	        }
845	      }
846	    }
847	  }
848	  return false;
849	}
850	
851	// find a sequence of `n` bits in a chunk with `n <= MI_BCHUNK_BITS` with all bits set,
852	// and try to clear them atomically.
853	// set `*pidx` to its bit index (0 <= *pidx <= MI_BCHUNK_BITS - n) on success.
854	// This can cross bfield boundaries.
855	static mi_decl_noinline bool mi_bchunk_try_find_and_clearNC(mi_bchunk_t* chunk, size_t n, size_t* pidx, bool* did_temp_clear_bits) {
856	  if (n == 0 || n > MI_BCHUNK_BITS) return false;  // cannot be more than a chunk
857	
858	  // we first scan ahead to see if there is a range of `n` set bits, and only then try to clear atomically
859	  mi_assert_internal(n>0);
860	  const size_t skip_count = (n-1)/MI_BFIELD_BITS;
861	  size_t cidx;
862	  for (size_t i = 0; i < MI_BCHUNK_FIELDS - skip_count; i++)
863	  {
864	    size_t m = n;   // bits to go
865	
866	    // first field
867	    mi_bfield_t b = mi_atomic_load_relaxed(&chunk->bfields[i]);
868	    size_t ones = mi_bfield_clz(~b);
869	
870	    cidx = (i*MI_BFIELD_BITS) + (MI_BFIELD_BITS - ones);  // start index
871	    if (ones >= m) {
872	      // we found enough bits already!
873	      m = 0;
874	    }
875	    else if (ones > 0) {
876	      // keep scanning further fields until we have enough bits
877	      m -= ones;
878	      size_t j = 1;   // field count from i
879	      while (i+j < MI_BCHUNK_FIELDS) {
880	        mi_assert_internal(m > 0);
881	        b = mi_atomic_load_relaxed(&chunk->bfields[i+j]);
882	        ones = mi_bfield_ctz(~b);
883	        if (ones >= m) {
884	          // we found enough bits
885	          m = 0;
886	          break;
887	        }
888	        else if (ones == MI_BFIELD_BITS) {
889	          // not enough yet, proceed to the next field
890	          j++;
891	          m -= MI_BFIELD_BITS;
892	        }
893	        else {
894	          // the range was not enough, start from scratch
895	          i = i + j - 1;  // no need to re-scan previous fields, except the last one (with clz this time)
896	          mi_assert_internal(m>0);
897	          break;
898	        }
899	      }
900	    }
901	
902	    // did we find a range?
903	    if (m==0) {
904	      if (mi_bchunk_try_clearN(chunk, cidx, n, NULL, did_temp_clear_bits)) {
905	        // we cleared all atomically
906	        *pidx = cidx;
907	        mi_assert_internal(*pidx < MI_BCHUNK_BITS);
908	        mi_assert_internal(*pidx + n <= MI_BCHUNK_BITS);
909	        return true;
910	      }
911	      // note: if we fail for a small `n` on the first field, we don't rescan that field (as `i` is incremented)
912	    }
913	    // otherwise continue searching
914	  }
915	  return false;
916	}
