931	
932	
933	// are all bits in a bitmap chunk clear?
934	static inline bool mi_bchunk_all_are_clear_relaxed(mi_bchunk_t* chunk) {
935	  #if MI_OPT_SIMD && defined(__AVX2__) && (MI_BCHUNK_BITS==256)
936	  const __m256i vec = _mm256_load_si256((const __m256i*)chunk->bfields);
937	  return mi_mm256_is_zero(vec);
938	  #elif MI_OPT_SIMD &&  defined(__AVX2__) && (MI_BCHUNK_BITS==512)
939	  // a 64b cache-line contains the entire chunk anyway so load both at once
940	  const __m256i vec1 = _mm256_load_si256((const __m256i*)chunk->bfields);
941	  const __m256i vec2 = _mm256_load_si256(((const __m256i*)chunk->bfields)+1);
942	  return (mi_mm256_is_zero(_mm256_or_si256(vec1,vec2)));
943	  #elif MI_OPT_SIMD && (MI_BCHUNK_BITS==512) && MI_ARCH_ARM64
944	  const uint64x2_t v0 = vld1q_u64((uint64_t*)chunk->bfields);
945	  const uint64x2_t v1 = vld1q_u64((uint64_t*)chunk->bfields + 2);
946	  const uint64x2_t v2 = vld1q_u64((uint64_t*)chunk->bfields + 4);
947	  const uint64x2_t v3 = vld1q_u64((uint64_t*)chunk->bfields + 6);
948	  const uint64x2_t v  = vorrq_u64(vorrq_u64(v0,v1),vorrq_u64(v2,v3));
949	  return (vmaxvq_u32(vreinterpretq_u32_u64(v)) == 0);
950	  #else
951	  for (int i = 0; i < MI_BCHUNK_FIELDS; i++) {
952	    if (mi_atomic_load_relaxed(&chunk->bfields[i]) != 0) return false;
953	  }
954	  return true;
955	  #endif
956	}
957	
958	// are all bits in a bitmap chunk set?
959	static inline bool mi_bchunk_all_are_set_relaxed(mi_bchunk_t* chunk) {
960	#if MI_OPT_SIMD && defined(__AVX2__) && (MI_BCHUNK_BITS==256)
961	  const __m256i vec = _mm256_load_si256((const __m256i*)chunk->bfields);
962	  return mi_mm256_is_ones(vec);
963	#elif MI_OPT_SIMD &&  defined(__AVX2__) && (MI_BCHUNK_BITS==512)
964	  // a 64b cache-line contains the entire chunk anyway so load both at once
965	  const __m256i vec1 = _mm256_load_si256((const __m256i*)chunk->bfields);
966	  const __m256i vec2 = _mm256_load_si256(((const __m256i*)chunk->bfields)+1);
967	  return (mi_mm256_is_ones(_mm256_and_si256(vec1, vec2)));
968	#elif MI_OPT_SIMD && (MI_BCHUNK_BITS==512) && MI_ARCH_ARM64
969	  const uint64x2_t v0 = vld1q_u64((uint64_t*)chunk->bfields);
970	  const uint64x2_t v1 = vld1q_u64((uint64_t*)chunk->bfields + 2);
971	  const uint64x2_t v2 = vld1q_u64((uint64_t*)chunk->bfields + 4);
972	  const uint64x2_t v3 = vld1q_u64((uint64_t*)chunk->bfields + 6);
973	  const uint64x2_t v  = vandq_u64(vandq_u64(v0,v1),vandq_u64(v2,v3));
974	  return (vminvq_u32(vreinterpretq_u32_u64(v)) == 0xFFFFFFFFUL);
975	#else
976	  for (int i = 0; i < MI_BCHUNK_FIELDS; i++) {
977	    if (~mi_atomic_load_relaxed(&chunk->bfields[i]) != 0) return false;
978	  }
979	  return true;
980	#endif
981	}
