983	
984	static bool mi_bchunk_bsr(mi_bchunk_t* chunk, size_t* pidx) {
985	  for (size_t i = MI_BCHUNK_FIELDS; i > 0; ) {
986	    i--;
987	    mi_bfield_t b = mi_atomic_load_relaxed(&chunk->bfields[i]);
988	    size_t idx;
989	    if (mi_bsr(b, &idx)) {
990	      *pidx = (i*MI_BFIELD_BITS) + idx;
991	      return true;
992	    }
993	  }
994	  return false;
995	}
996	
997	static bool mi_bchunk_bsr_inv(mi_bchunk_t* chunk, size_t* pidx) {  
998	  for (size_t i = MI_BCHUNK_FIELDS; i > 0; ) {
999	    i--;
1000	    mi_bfield_t b = mi_atomic_load_relaxed(&chunk->bfields[i]);
1001	    size_t idx;
1002	    if (mi_bsr(~b, &idx)) {
1003	      *pidx = (i*MI_BFIELD_BITS) + idx;
1004	      return true;
1005	    }
1006	  }
1007	  return false;
1008	}
1009	
1010	static size_t mi_bchunk_popcount(mi_bchunk_t* chunk) {
1011	  size_t popcount = 0;
1012	  for (size_t i = 0; i < MI_BCHUNK_FIELDS; i++) {
1013	    const mi_bfield_t b = mi_atomic_load_relaxed(&chunk->bfields[i]);
1014	    popcount += mi_bfield_popcount(b);
1015	  }
1016	  return popcount;
1017	}
