1024	static void mi_bitmap_chunkmap_set(mi_bitmap_t* bitmap, size_t chunk_idx) {
1025	  mi_assert(chunk_idx < mi_bitmap_chunk_count(bitmap));
1026	  mi_bchunk_set(&bitmap->chunkmap, chunk_idx, NULL);
1027	}
