1029	static bool mi_bitmap_chunkmap_try_clear(mi_bitmap_t* bitmap, size_t chunk_idx) {
1030	  mi_assert(chunk_idx < mi_bitmap_chunk_count(bitmap));
1031	  // check if the corresponding chunk is all clear
1032	  if (!mi_bchunk_all_are_clear_relaxed(&bitmap->chunks[chunk_idx])) return false;
1033	  // clear the chunkmap bit
1034	  mi_bchunk_clear(&bitmap->chunkmap, chunk_idx, NULL);
1035	  // .. but a concurrent set may have happened in between our all-clear test and the clearing of the
1036	  // bit in the mask. We check again to catch this situation.
1037	  if (!mi_bchunk_all_are_clear_relaxed(&bitmap->chunks[chunk_idx])) {
1038	    mi_bchunk_set(&bitmap->chunkmap, chunk_idx, NULL);
1039	    return false;
1040	  }
1041	  return true;
1042	}
