1049	size_t mi_bitmap_size(size_t bit_count, size_t* pchunk_count) {
1050	  mi_assert_internal((bit_count % MI_BCHUNK_BITS) == 0);
1051	  bit_count = _mi_align_up(bit_count, MI_BCHUNK_BITS);
1052	  mi_assert_internal(bit_count <= MI_BITMAP_MAX_BIT_COUNT);
1053	  mi_assert_internal(bit_count > 0);
1054	  const size_t chunk_count = bit_count / MI_BCHUNK_BITS;
1055	  mi_assert_internal(chunk_count >= 1);
1056	  const size_t size = offsetof(mi_bitmap_t,chunks) + (chunk_count * MI_BCHUNK_SIZE);
1057	  mi_assert_internal( (size%MI_BCHUNK_SIZE) == 0 );
1058	  if (pchunk_count != NULL) { *pchunk_count = chunk_count;  }
1059	  return size;
1060	}
