1063	// initialize a bitmap to all unset; avoid a mem_zero if `already_zero` is true
1064	// returns the size of the bitmap
1065	size_t mi_bitmap_init(mi_bitmap_t* bitmap, size_t bit_count, bool already_zero) {
1066	  size_t chunk_count;
1067	  const size_t size = mi_bitmap_size(bit_count, &chunk_count);
1068	  if (!already_zero) {
1069	    _mi_memzero_aligned(bitmap, size);
1070	  }
1071	  mi_atomic_store_release(&bitmap->chunk_count, chunk_count);
1072	  mi_assert_internal(mi_atomic_load_relaxed(&bitmap->chunk_count) <= MI_BITMAP_MAX_CHUNK_COUNT);
1073	  return size;
1074	}
