1077	// Set a sequence of `n` bits in the bitmap (and can cross chunks). Not atomic so only use if local to a thread.
1078	static void mi_bchunks_unsafe_setN(mi_bchunk_t* chunks, mi_bchunkmap_t* cmap, size_t idx, size_t n) {
1079	  mi_assert_internal(n>0);
1080	
1081	  // start chunk and index
1082	  size_t chunk_idx = idx / MI_BCHUNK_BITS;
1083	  const size_t cidx = idx % MI_BCHUNK_BITS;
1084	  const size_t ccount = _mi_divide_up(n, MI_BCHUNK_BITS);
1085	
1086	  // first update the chunkmap
1087	  mi_bchunk_setN(cmap, chunk_idx, ccount, NULL);
1088	
1089	  // first chunk
1090	  size_t m = MI_BCHUNK_BITS - cidx;
1091	  if (m > n) { m = n; }
1092	  mi_bchunk_setN(&chunks[chunk_idx], cidx, m, NULL);
1093	
1094	  // n can be large so use memset for efficiency for all in-between chunks
1095	  chunk_idx++;
1096	  n -= m;
1097	  const size_t mid_chunks = n / MI_BCHUNK_BITS;
1098	  if (mid_chunks > 0) {
1099	    _mi_memset(&chunks[chunk_idx], ~0, mid_chunks * MI_BCHUNK_SIZE);
1100	    chunk_idx += mid_chunks;
1101	    n -= (mid_chunks * MI_BCHUNK_BITS);
1102	  }
1103	
1104	  // last chunk
1105	  if (n > 0) {
1106	    mi_assert_internal(n < MI_BCHUNK_BITS);
1107	    mi_bchunk_setN(&chunks[chunk_idx], 0, n, NULL);
1108	  }
1109	}
