1111	// Set a sequence of `n` bits in the bitmap (and can cross chunks). Not atomic so only use if local to a thread.
1112	void mi_bitmap_unsafe_setN(mi_bitmap_t* bitmap, size_t idx, size_t n) {
1113	  mi_assert_internal(n>0);
1114	  mi_assert_internal(idx + n <= mi_bitmap_max_bits(bitmap));
1115	  mi_bchunks_unsafe_setN(&bitmap->chunks[0], &bitmap->chunkmap, idx, n);
1116	}
