1121	// ------- mi_bitmap_xset ---------------------------------------
1122	
1123	// Set a sequence of `n` bits in the bitmap; returns `true` if atomically transitioned from 0's to 1's (or 1's to 0's).
1124	bool mi_bitmap_setN(mi_bitmap_t* bitmap, size_t idx, size_t n, size_t* palready_set) {
1125	  mi_assert_internal(n>0);
1126	  const size_t maxbits = mi_bitmap_max_bits(bitmap);
1127	  mi_assert_internal(idx + n <= maxbits);
1128	  if (idx+n > maxbits) { // paranoia
1129	    if (idx >= maxbits) return false;
1130	    n = maxbits - idx;
1131	  }
1132	
1133	  // iterate through the chunks
1134	  size_t chunk_idx = idx / MI_BCHUNK_BITS;
1135	  size_t cidx = idx % MI_BCHUNK_BITS;
1136	  bool were_allclear = true;
1137	  size_t already_set = 0;
1138	  while (n > 0) {
1139	    const size_t m = (cidx + n > MI_BCHUNK_BITS ? MI_BCHUNK_BITS - cidx : n);
1140	    size_t _already_set = 0;
1141	    were_allclear = mi_bchunk_setN(&bitmap->chunks[chunk_idx], cidx, m, &_already_set) && were_allclear;
1142	    already_set += _already_set;
1143	    mi_bitmap_chunkmap_set(bitmap, chunk_idx); // set afterwards
1144	    mi_assert_internal(m <= n);
1145	    n -= m;
1146	    cidx = 0;
1147	    chunk_idx++;
1148	  }
1149	  if (palready_set != NULL) { *palready_set = already_set;  }
1150	  return were_allclear;
1151	}
