1153	// Clear a sequence of `n` bits in the bitmap; returns `true` if atomically transitioned from 1's to 0's.
1154	bool mi_bitmap_clearN(mi_bitmap_t* bitmap, size_t idx, size_t n) {
1155	  mi_assert_internal(n>0);
1156	  const size_t maxbits = mi_bitmap_max_bits(bitmap);
1157	  mi_assert_internal(idx + n <= maxbits);
1158	  if (idx+n > maxbits) { // paranoia
1159	    if (idx >= maxbits) return false;
1160	    n = maxbits - idx;
1161	  }
1162	
1163	  // iterate through the chunks
1164	  size_t chunk_idx = idx / MI_BCHUNK_BITS;
1165	  size_t cidx = idx % MI_BCHUNK_BITS;
1166	  bool were_allset = true;
1167	  while (n > 0) {
1168	    const size_t m = (cidx + n > MI_BCHUNK_BITS ? MI_BCHUNK_BITS - cidx : n);
1169	    bool maybe_all_clear = false;
1170	    were_allset = mi_bchunk_clearN(&bitmap->chunks[chunk_idx], cidx, m, &maybe_all_clear) && were_allset;
1171	    if (maybe_all_clear) { mi_bitmap_chunkmap_try_clear(bitmap, chunk_idx); }
1172	    mi_assert_internal(m <= n);
1173	    n -= m;
1174	    cidx = 0;
1175	    chunk_idx++;
1176	  }
1177	  return were_allset;
1178	}
