1180	// Count bits set in a range of `n` bits.
1181	size_t mi_bitmap_popcountN( mi_bitmap_t* bitmap, size_t idx, size_t n) {
1182	  mi_assert_internal(n>0);
1183	  const size_t maxbits = mi_bitmap_max_bits(bitmap);
1184	  mi_assert_internal(idx + n <= maxbits);
1185	  if (idx+n > maxbits) { // paranoia
1186	    if (idx >= maxbits) return 0;
1187	    n = maxbits - idx;
1188	  }
1189	
1190	  // iterate through the chunks
1191	  size_t chunk_idx = idx / MI_BCHUNK_BITS;
1192	  size_t cidx = idx % MI_BCHUNK_BITS;
1193	  size_t popcount = 0;
1194	  while (n > 0) {
1195	    const size_t m = (cidx + n > MI_BCHUNK_BITS ? MI_BCHUNK_BITS - cidx : n);
1196	    popcount += mi_bchunk_popcountN(&bitmap->chunks[chunk_idx], cidx, m);
1197	    mi_assert_internal(m <= n);
1198	    n -= m;
1199	    cidx = 0;
1200	    chunk_idx++;
1201	  }
1202	  return popcount;
1203	}
