1219	// Is a sequence of n bits already all set/cleared?
1220	bool mi_bitmap_is_xsetN(mi_xset_t set, mi_bitmap_t* bitmap, size_t idx, size_t n) {
1221	  mi_assert_internal(n>0);
1222	  const size_t maxbits = mi_bitmap_max_bits(bitmap);
1223	  mi_assert_internal(idx + n <= maxbits);
1224	  if (idx+n > maxbits) { // paranoia
1225	    if (idx >= maxbits) return false;
1226	    n = maxbits - idx;
1227	  }
1228	
1229	  // iterate through the chunks
1230	  size_t chunk_idx = idx / MI_BCHUNK_BITS;
1231	  size_t cidx = idx % MI_BCHUNK_BITS;
1232	  bool xset = true;
1233	  while (n > 0 && xset) {
1234	    const size_t m = (cidx + n > MI_BCHUNK_BITS ? MI_BCHUNK_BITS - cidx : n);
1235	    xset = mi_bchunk_is_xsetN(set, &bitmap->chunks[chunk_idx], cidx, m) && xset;
1236	    mi_assert_internal(m <= n);
1237	    n -= m;
1238	    cidx = 0;
1239	    chunk_idx++;
1240	  }
1241	  return xset;
1242	}
