1248	/* --------------------------------------------------------------------------------
1249	  Iterate through a bfield
1250	-------------------------------------------------------------------------------- */
1251	
1252	// Cycle iteration through a bitfield. This is used to space out threads
1253	// so there is less chance of contention. When searching for a free page we
1254	// like to first search only the accessed part (so we reuse better). This
1255	// high point is called the `cycle`.
1256	//
1257	// We then iterate through the bitfield as:
1258	// first: [start, cycle>
1259	// then : [0, start>
1260	// then : [cycle, MI_BFIELD_BITS>
1261	//
1262	// The start is determined usually as `tseq % cycle` to have each thread
1263	// start at a different spot.
1264	// - We use `popcount` to improve branch prediction (maybe not needed? can we simplify?)
1265	// - The `cycle_mask` is the part `[start, cycle>`.
1266	#define mi_bfield_iterate(bfield,start,cycle,name_idx,SUF) { \
1267	  mi_assert_internal(start <= cycle); \
1268	  mi_assert_internal(start < MI_BFIELD_BITS); \
1269	  mi_assert_internal(cycle <= MI_BFIELD_BITS); \
1270	  const mi_bfield_t _cycle_mask##SUF = mi_bfield_mask(cycle - start, start); \
1271	  size_t _bcount##SUF = mi_bfield_popcount(bfield); \
1272	  mi_bfield_t _b##SUF = bfield & _cycle_mask##SUF; /* process [start, cycle> first*/\
1273	  while(_bcount##SUF > 0) { \
1274	    _bcount##SUF--;\
1275	    if (_b##SUF==0) { _b##SUF = bfield & ~_cycle_mask##SUF; } /* process [0,start> + [cycle, MI_BFIELD_BITS> next */ \
1276	    /* size_t name_idx; */ \
1277	    const bool _found##SUF = mi_bfield_find_least_bit(_b##SUF,&name_idx); \
1278	    _b##SUF = mi_bfield_clear_least_bit(_b##SUF); /* clear early so `continue` works */ \
1279	    mi_assert_internal(_found##SUF); MI_UNUSED(_found##SUF); \
1280	    { \
1281	
1282	#define mi_bfield_iterate_end(SUF) \
1283	    } \
1284	  } \
1285	}
1286	
1287	
1288	#define mi_bfield_cycle_iterate(bfield,tseq,cycle,name_idx,SUF) { \
1289	  const size_t _start##SUF = (uint32_t)(tseq) % (uint32_t)(cycle); /* or: 0 to always search from the start? */\
1290	  mi_bfield_iterate(bfield,_start##SUF,cycle,name_idx,SUF)
1291	
1292	#define mi_bfield_cycle_iterate_end(SUF) \
1293	  mi_bfield_iterate_end(SUF); \
1294	}
