1405	// Return count of all set bits in a bitmap.
1406	size_t mi_bitmap_popcount(mi_bitmap_t* bitmap) {
1407	  // for all chunkmap entries
1408	  size_t popcount = 0;
1409	  const size_t chunkmap_max = _mi_divide_up(mi_bitmap_chunk_count(bitmap), MI_BFIELD_BITS);
1410	  for (size_t i = 0; i < chunkmap_max; i++) {
1411	    mi_bfield_t cmap_entry = mi_atomic_load_relaxed(&bitmap->chunkmap.bfields[i]);
1412	    size_t cmap_idx;
1413	    // for each chunk (corresponding to a set bit in a chunkmap entry)
1414	    while (mi_bfield_foreach_bit(&cmap_entry, &cmap_idx)) {
1415	      const size_t chunk_idx = i*MI_BFIELD_BITS + cmap_idx;
1416	      // count bits in a chunk
1417	      popcount += mi_bchunk_popcount(&bitmap->chunks[chunk_idx]);
1418	    }
1419	  }
1420	  return popcount;
1421	}
