1435	// Visit all set bits in a bitmap.
1436	// todo: optimize further? maybe use avx512 to directly get all indices using a mask_compressstore?
1437	bool _mi_bitmap_forall_set(mi_bitmap_t* bitmap, mi_forall_set_fun_t* visit, mi_arena_t* arena, void* arg) {
1438	  // for all chunkmap entries
1439	  const size_t chunkmap_max = _mi_divide_up(mi_bitmap_chunk_count(bitmap), MI_BFIELD_BITS);
1440	  for(size_t i = 0; i < chunkmap_max; i++) {
1441	    mi_bfield_t cmap_entry = mi_atomic_load_relaxed(&bitmap->chunkmap.bfields[i]);
1442	    size_t cmap_idx;
1443	    // for each chunk (corresponding to a set bit in a chunkmap entry)
1444	    while (mi_bfield_foreach_bit(&cmap_entry, &cmap_idx)) {
1445	      const size_t chunk_idx = i*MI_BFIELD_BITS + cmap_idx;
1446	      // for each chunk field
1447	      mi_bchunk_t* const chunk = &bitmap->chunks[chunk_idx];
1448	      for (size_t j = 0; j < MI_BCHUNK_FIELDS; j++) {
1449	        const size_t base_idx = (chunk_idx*MI_BCHUNK_BITS) + (j*MI_BFIELD_BITS);
1450	        mi_bfield_t b = mi_atomic_load_relaxed(&chunk->bfields[j]);
1451	        size_t bidx;
1452	        while (mi_bfield_foreach_bit(&b, &bidx)) {
1453	          const size_t idx = base_idx + bidx;
1454	          if (!visit(idx, 1, arena, arg)) return false;
1455	        }
1456	      }
1457	    }
1458	  }
1459	  return true;
1460	}
1461	
1462	// Visit all set bits in a bitmap but try to return ranges (within bfields) if possible.
1463	// Also clear those ranges atomically.
1464	// Used by purging to purge larger ranges when possible
1465	// todo: optimize further? maybe use avx512 to directly get all indices using a mask_compressstore?
1466	bool _mi_bitmap_forall_setc_ranges(mi_bitmap_t* bitmap, mi_forall_set_fun_t* visit, mi_arena_t* arena, void* arg) {
1467	  // for all chunkmap entries
1468	  const size_t chunkmap_max = _mi_divide_up(mi_bitmap_chunk_count(bitmap), MI_BFIELD_BITS);
1469	  for (size_t i = 0; i < chunkmap_max; i++) {
1470	    mi_bfield_t cmap_entry = mi_atomic_load_relaxed(&bitmap->chunkmap.bfields[i]);
1471	    size_t cmap_idx;
1472	    // for each chunk (corresponding to a set bit in a chunkmap entry)
1473	    while (mi_bfield_foreach_bit(&cmap_entry, &cmap_idx)) {
1474	      const size_t chunk_idx = i*MI_BFIELD_BITS + cmap_idx;
1475	      // for each chunk field
1476	      mi_bchunk_t* const chunk = &bitmap->chunks[chunk_idx];
1477	      for (size_t j = 0; j < MI_BCHUNK_FIELDS; j++) {
1478	        const size_t base_idx = (chunk_idx*MI_BCHUNK_BITS) + (j*MI_BFIELD_BITS);
1479	        mi_bfield_t b = mi_atomic_exchange_relaxed(&chunk->bfields[j], (mi_bfield_t)0);
1480	        #if MI_DEBUG > 1
1481	        const size_t bpopcount = mi_popcount(b);
1482	        size_t rngcount = 0;
1483	        #endif
1484	        size_t bidx;
1485	        while (mi_bfield_find_least_bit(b, &bidx)) {
1486	          size_t rng = mi_ctz(~(b>>bidx)); // all the set bits from bidx
1487	          #if MI_DEBUG > 1
1488	          rngcount += rng;
1489	          #endif
1490	          const size_t idx = base_idx + bidx;
1491	          mi_assert_internal(rng>=1 && rng<=MI_BFIELD_BITS);
1492	          mi_assert_internal((idx % MI_BFIELD_BITS) + rng <= MI_BFIELD_BITS);
1493	          mi_assert_internal((idx / MI_BCHUNK_BITS) < mi_bitmap_chunk_count(bitmap));
1494	          // clear rng bits in b
1495	          b = b & ~mi_bfield_mask(rng, bidx);
1496	          if (!visit(idx, rng, arena, arg)) {
1497	            // break early: reset the non-visited bits
1498	            if (b!=0) {
1499	              mi_atomic_or_relaxed(&chunk->bfields[j], b);
1500	            }
1501	            return false;
1502	          }
1503	        }
1504	        mi_assert_internal(rngcount == bpopcount);
1505	      }
1506	    }
1507	  }
1508	  return true;
1509	}
1510	
1511	// Visit all set bits in a bitmap but try to return ranges (within bfields) if possible,
1512	// but only in chunks of at least `rngslices` slices (that are also aligned at `rngslices`)
1513	// and clear those ranges atomically.
1514	// However, the `rngslices` are capped at `MI_BFIELD_BITS` at most.
1515	// Used by purging to purge larger ranges when possible. With transparent huge pages we only
1516	// want to purge whole huge pages (2 MiB) at a time which is what the `rngslices` parameter achieves.
1517	bool _mi_bitmap_forall_setc_rangesn(mi_bitmap_t* bitmap, size_t rngslices, mi_forall_set_fun_t* visit, mi_arena_t* arena, void* arg) 
1518	{
1519	  // use the generic routine for `rngslices<=1` (as that one finds longest ranges at a time)
1520	  if (rngslices<=1) {
1521	    return _mi_bitmap_forall_setc_ranges(bitmap, visit, arena, arg);
1522	  }
1523	  // mi_assert_internal(rngslices <= MI_BFIELD_BITS);  
1524	  if (rngslices > MI_BFIELD_BITS) { rngslices = MI_BFIELD_BITS;  } // cap at MI_BFIELD_BITS at most
1525	
1526	  // for all chunkmap entries
1527	  const size_t chunkmap_max = _mi_divide_up(mi_bitmap_chunk_count(bitmap), MI_BFIELD_BITS);
1528	  for (size_t i = 0; i < chunkmap_max; i++) {
1529	    mi_bfield_t cmap_entry = mi_atomic_load_relaxed(&bitmap->chunkmap.bfields[i]);
1530	    size_t cmap_idx;
1531	    // for each chunk (corresponding to a set bit in a chunkmap entry)
1532	    while (mi_bfield_foreach_bit(&cmap_entry, &cmap_idx)) {
1533	      const size_t chunk_idx = i*MI_BFIELD_BITS + cmap_idx;
1534	      // for each chunk field
1535	      mi_bchunk_t* const chunk = &bitmap->chunks[chunk_idx];
1536	      for (size_t j = 0; j < MI_BCHUNK_FIELDS; j++) {
1537	        const size_t base_idx = (chunk_idx*MI_BCHUNK_BITS) + (j*MI_BFIELD_BITS);
1538	        mi_bfield_t b = mi_atomic_exchange_relaxed(&chunk->bfields[j], (mi_bfield_t)0);   // atomic clear
1539	        mi_bfield_t skipped = 0;                                                          // but track which bits we skip so we can restore them
1540	        size_t shift;
1541	        for(shift = 0; rngslices + shift <= MI_BFIELD_BITS; shift += rngslices) {  // per `rngslices` to keep alignment
1542	          const mi_bfield_t rngmask = mi_bfield_mask(rngslices, shift);
1543	          if ((b & rngmask) == rngmask) {
1544	            const size_t idx = base_idx + shift;
1545	            if (!visit(idx, rngslices, arena, arg)) {
1546	              // break early: restore non-visited entries
1547	              mi_bfield_t notyet_visited = 0;
1548	              if (rngslices + shift < MI_BFIELD_BITS) {
1549	                notyet_visited = (b & (~(mi_bfield_t)0 << (shift + rngslices)));
1550	              }
1551	              mi_assert_internal((notyet_visited & skipped) == 0);
1552	              if ((notyet_visited | skipped) != 0) {
1553	                mi_atomic_or_relaxed(&chunk->bfields[j], notyet_visited | skipped);
1554	              }
1555	              return false;
1556	            }
1557	          }
1558	          else {
1559	            skipped = skipped | (b & rngmask);
1560	          }          
1561	        } 
1562	        if (shift < MI_BFIELD_BITS) {
1563	          // there are some non-visited top bits when `MI_BFIELD_BITS % rngslices != 0`.
1564	          mi_assert_internal(MI_BFIELD_BITS % rngslices != 0);
1565	          skipped = skipped | (b & (~(mi_bfield_t)0 << shift));
1566	        }
1567	        if (skipped != 0) {
1568	          //  restore non-visited entries
1569	          mi_atomic_or_relaxed(&chunk->bfields[j], skipped);
1570	        }
1571	      }
1572	    }
1573	  }
1574	  return true;
1575	}
