1583	size_t mi_bbitmap_size(size_t bit_count, size_t* pchunk_count) {
1584	  // mi_assert_internal((bit_count % MI_BCHUNK_BITS) == 0);
1585	  bit_count = _mi_align_up(bit_count, MI_BCHUNK_BITS);
