1587	  mi_assert_internal(bit_count > 0);
1588	  const size_t chunk_count = bit_count / MI_BCHUNK_BITS;
1589	  mi_assert_internal(chunk_count >= 1);
1590	  const size_t size = offsetof(mi_bbitmap_t,chunks) + (chunk_count * MI_BCHUNK_SIZE);
1591	  mi_assert_internal( (size%MI_BCHUNK_SIZE) == 0 );
1592	  if (pchunk_count != NULL) { *pchunk_count = chunk_count;  }
1593	  return size;
