1616	bool mi_bbitmap_bsr_inv(mi_bbitmap_t* bbitmap, size_t* idx) {
1617	  // scan for highest zero bit in the bitmap
1618	  // note: we cannot use the chunkmap since that only conservatively denotes if there might be a set bit in a chuck
1619	  // todo: bbitmap_init rounds up the bitcount to BCHUNK_BITS and we should skip the top-padding!
1620	  const size_t chunk_count = mi_bbitmap_chunk_count(bbitmap);
1621	  for(size_t i = chunk_count; i > 0; ) {
1622	    i--;
1623	    size_t cidx;
1624	    if (mi_bchunk_bsr_inv(&bbitmap->chunks[i], &cidx)) {
1625	      *idx = (i * MI_BCHUNK_BITS) + cidx;
