1661	// Track the index of the highest chunk that is accessed.
1662	static void mi_bbitmap_chunkmap_set_max(mi_bbitmap_t* bbitmap, size_t chunk_idx) {
1663	  size_t oldmax = mi_atomic_load_relaxed(&bbitmap->chunk_max_accessed);
1664	  if mi_unlikely(chunk_idx > oldmax) {
1665	    mi_atomic_cas_strong_relaxed(&bbitmap->chunk_max_accessed, &oldmax, chunk_idx);
1666	  }
