1669	// Set a bit in the chunkmap
1670	static void mi_bbitmap_chunkmap_set(mi_bbitmap_t* bbitmap, size_t chunk_idx, bool check_all_set) {
1671	  mi_assert(chunk_idx < mi_bbitmap_chunk_count(bbitmap));
1672	  if (check_all_set) {
1673	    if (mi_bchunk_all_are_set_relaxed(&bbitmap->chunks[chunk_idx])) {
1674	      // all slices are free in this chunk: return back to the NONE bin
1675	      mi_bbitmap_set_chunk_bin(bbitmap, chunk_idx, MI_CBIN_NONE);
1676	    }
1677	  }
1678	  mi_bchunk_set(&bbitmap->chunkmap, chunk_idx, NULL);
1679	  mi_bbitmap_chunkmap_set_max(bbitmap, chunk_idx);
1680	}
