1682	static bool mi_bbitmap_chunkmap_try_clear(mi_bbitmap_t* bbitmap, size_t chunk_idx) {
1683	  mi_assert(chunk_idx < mi_bbitmap_chunk_count(bbitmap));
1684	  // check if the corresponding chunk is all clear
1685	  if (!mi_bchunk_all_are_clear_relaxed(&bbitmap->chunks[chunk_idx])) return false;
1686	  // clear the chunkmap bit
1687	  mi_bchunk_clear(&bbitmap->chunkmap, chunk_idx, NULL);
1688	  // .. but a concurrent set may have happened in between our all-clear test and the clearing of the
1689	  // bit in the mask. We check again to catch this situation. (note: mi_bchunk_clear must be acq-rel)
1690	  if (!mi_bchunk_all_are_clear_relaxed(&bbitmap->chunks[chunk_idx])) {
1691	    mi_bchunk_set(&bbitmap->chunkmap, chunk_idx, NULL);
1692	    return false;
1693	  }
1694	  mi_bbitmap_chunkmap_set_max(bbitmap, chunk_idx);
1695	  return true;
1696	}
