1699	/* --------------------------------------------------------------------------------
1700	  mi_bbitmap_setN, try_clearN, and is_xsetN
1701	  (used to find free pages)
1702	-------------------------------------------------------------------------------- */
1703	
1704	// Set a sequence of `n` bits in the bitmap; returns `true` if atomically transitioned from 0's to 1's (or 1's to 0's).
1705	bool mi_bbitmap_setN(mi_bbitmap_t* bbitmap, size_t idx, size_t n) {
1706	  mi_assert_internal(n>0);
1707	  const size_t maxbits = mi_bbitmap_max_bits(bbitmap);
1708	  mi_assert_internal(idx + n <= maxbits);
1709	  if (idx+n > maxbits) { // paranoia
1710	    if (idx >= maxbits) return false;
1711	    n = maxbits - idx;
1712	  }
1713	
1714	  // iterate through the chunks
1715	  size_t chunk_idx = idx / MI_BCHUNK_BITS;
1716	  size_t cidx = idx % MI_BCHUNK_BITS;
1717	  bool were_allclear = true;
1718	  while (n > 0) {
1719	    const size_t m = (cidx + n > MI_BCHUNK_BITS ? MI_BCHUNK_BITS - cidx : n);
1720	    were_allclear = mi_bchunk_setN(&bbitmap->chunks[chunk_idx], cidx, m, NULL) && were_allclear;
1721	    mi_bbitmap_chunkmap_set(bbitmap, chunk_idx, true); // set afterwards
1722	    mi_assert_internal(m <= n);
1723	    n -= m;
1724	    cidx = 0;
1725	    chunk_idx++;
1726	  }
1727	  return were_allclear;
1728	}
1729	
1730	// ------- mi_bbitmap_try_clearNC ---------------------------------------
1731	
1732	// Try to clear `n` bits at `idx` where `n <= MI_BCHUNK_BITS`.
1733	bool mi_bbitmap_try_clearNC(mi_bbitmap_t* bbitmap, size_t idx, size_t n) {
1734	  mi_assert_internal(n>0);
1735	  mi_assert_internal(n<=MI_BCHUNK_BITS);
1736	  mi_assert_internal(idx + n <= mi_bbitmap_max_bits(bbitmap));
1737	
1738	  const size_t chunk_idx = idx / MI_BCHUNK_BITS;
1739	  const size_t cidx = idx % MI_BCHUNK_BITS;
1740	  mi_assert_internal(cidx + n <= MI_BCHUNK_BITS);  // don't cross chunks (for now)
1741	  mi_assert_internal(chunk_idx < mi_bbitmap_chunk_count(bbitmap));
1742	  if (cidx + n > MI_BCHUNK_BITS) return false;
1743	  bool maybe_all_clear = false;
1744	  bool did_temp_clear_bits = false;
1745	  const bool cleared = mi_bchunk_try_clearN(&bbitmap->chunks[chunk_idx], cidx, n, &maybe_all_clear, &did_temp_clear_bits);
1746	  if (cleared && maybe_all_clear) { 
1747	    mi_assert_internal(!did_temp_clear_bits);
1748	    mi_bbitmap_chunkmap_try_clear(bbitmap, chunk_idx); 
1749	  } else if (did_temp_clear_bits) {
1750	    // may have raced with a clearer (in on_find) so set the chunkmap bit conservatively
1751	    mi_bbitmap_chunkmap_set(bbitmap, chunk_idx, false);
1752	  }
1753	  // note: we don't set the size class for an explicit try_clearN (only used by purging)
1754	  return cleared;
1755	}
