1759	// ------- mi_bbitmap_is_xset ---------------------------------------
1760	
1761	// Is a sequence of n bits already all set/cleared?
1762	bool mi_bbitmap_is_xsetN(mi_xset_t set, mi_bbitmap_t* bbitmap, size_t idx, size_t n) {
1763	  mi_assert_internal(n>0);
1764	  const size_t maxbits = mi_bbitmap_max_bits(bbitmap);
1765	  mi_assert_internal(idx + n <= maxbits);
1766	  if (idx+n > maxbits) { // paranoia
1767	    if (idx >= maxbits) return false;
1768	    n = maxbits - idx;
1769	  }
1770	
1771	  // iterate through the chunks
1772	  size_t chunk_idx = idx / MI_BCHUNK_BITS;
1773	  size_t cidx = idx % MI_BCHUNK_BITS;
1774	  bool xset = true;
1775	  while (n > 0 && xset) {
1776	    const size_t m = (cidx + n > MI_BCHUNK_BITS ? MI_BCHUNK_BITS - cidx : n);
1777	    xset = mi_bchunk_is_xsetN(set, &bbitmap->chunks[chunk_idx], cidx, m) && xset;
1778	    mi_assert_internal(m <= n);
1779	    n -= m;
1780	    cidx = 0;
1781	    chunk_idx++;
1782	  }
1783	  return xset;
1784	}
