1789	/* --------------------------------------------------------------------------------
1790	  mi_bbitmap_find
1791	  (used to find free pages)
1792	-------------------------------------------------------------------------------- */
1793	
1794	typedef bool (mi_bchunk_try_find_and_clear_fun_t)(mi_bchunk_t* chunk, size_t n, size_t* idx, bool* did_temp_clear_bits);
1795	
1796	// Go through the bbitmap and for every sequence of `n` set bits, call the visitor function.
1797	// If it returns `true` stop the search.
1798	//
1799	// This is used for finding free blocks and it is important to be efficient (with 2-level bitscan)
1800	// but also reduce fragmentation (through size bins).
1801	static bool mi_bbitmap_try_find_and_clear_generic(mi_bbitmap_t* bbitmap, size_t tseq, size_t n, size_t* pidx, mi_bchunk_try_find_and_clear_fun_t* on_find)
1802	{
1803	  // we space out threads to reduce contention
1804	  const size_t cmap_max_count  = _mi_divide_up(mi_bbitmap_chunk_count(bbitmap),MI_BFIELD_BITS);
1805	  const size_t chunk_acc       = mi_atomic_load_relaxed(&bbitmap->chunk_max_accessed);
1806	  const size_t cmap_acc        = chunk_acc / MI_BFIELD_BITS;
1807	  const size_t cmap_acc_bits   = 1 + (chunk_acc % MI_BFIELD_BITS);
1808	
1809	  // create a mask over the chunkmap entries to iterate over them efficiently
1810	  mi_assert_internal(MI_BFIELD_BITS >= MI_BCHUNK_FIELDS);
1811	  const mi_bfield_t cmap_mask  = mi_bfield_mask(cmap_max_count,0);
1812	  const size_t cmap_cycle      = cmap_acc+1;
1813	  const mi_chunkbin_t bbin = mi_chunkbin_of(n);
1814	  // visit each cmap entry
1815	  size_t cmap_idx = 0;
1816	  mi_bfield_cycle_iterate(cmap_mask, tseq, cmap_cycle, cmap_idx, X)
1817	  {
1818	    // and for each chunkmap entry we iterate over its bits to find the chunks
1819	    const mi_bfield_t cmap_entry = mi_atomic_load_relaxed(&bbitmap->chunkmap.bfields[cmap_idx]);
1820	    const size_t cmap_entry_cycle = (cmap_idx != cmap_acc ? MI_BFIELD_BITS : cmap_acc_bits);
1821	    if (cmap_entry == 0) {
1822	      continue;
1823	    }
1824	
1825	    // get size bin masks
1826	    mi_bfield_t cmap_bins[MI_CBIN_COUNT] = { 0 };
1827	    cmap_bins[MI_CBIN_NONE] = cmap_entry;
1828	    for (mi_chunkbin_t ibin = MI_CBIN_SMALL; ibin < MI_CBIN_NONE; ibin = mi_chunkbin_inc(ibin)) {
1829	      const mi_bfield_t cmap_bin = mi_atomic_load_relaxed(&bbitmap->chunkmap_bins[ibin].bfields[cmap_idx]);
1830	      cmap_bins[ibin] = cmap_bin & cmap_entry;
1831	      cmap_bins[MI_CBIN_NONE] &= ~cmap_bin;      // clear bits that are in an assigned size bin
1832	    }
1833	
1834	    // consider only chunks for a particular size bin at a time
1835	    // this picks the best bin only within a cmap entry (~ 1GiB address space), but avoids multiple
1836	    // iterations through all entries.
1837	    mi_assert_internal(bbin < MI_CBIN_NONE);
1838	    for (mi_chunkbin_t ibin = MI_CBIN_SMALL; ibin <= MI_CBIN_NONE;
1839	          // skip from bbin to NONE (so, say, a SMALL will never be placed in a OTHER, MEDIUM, or LARGE chunk to reduce fragmentation)
1840	          ibin = (ibin == bbin ? MI_CBIN_NONE : mi_chunkbin_inc(ibin)))
1841	    {
1842	      mi_assert_internal(ibin < MI_CBIN_COUNT);
1843	      const mi_bfield_t cmap_bin = cmap_bins[ibin];
1844	      size_t eidx = 0;
1845	      mi_bfield_cycle_iterate(cmap_bin, tseq, cmap_entry_cycle, eidx, Y)
1846	      {
1847	        // assertion doesn't quite hold as the max_accessed may be out-of-date
1848	        // mi_assert_internal(cmap_entry_cycle > eidx || ibin == MI_CBIN_NONE);
1849	
1850	        // get the chunk
1851	        const size_t chunk_idx = cmap_idx*MI_BFIELD_BITS + eidx;
1852	        mi_bchunk_t* chunk = &bbitmap->chunks[chunk_idx];
1853	
1854	        size_t cidx;
1855	        bool did_temp_clear_bits = false;
1856	        if ((*on_find)(chunk, n, &cidx, &did_temp_clear_bits)) {
1857	          if (cidx==0 && ibin == MI_CBIN_NONE) { // only the first block determines the size bin
1858	            // this chunk is now reserved for the `bbin` size class
1859	            mi_bbitmap_set_chunk_bin(bbitmap, chunk_idx, bbin);
1860	          }
1861	          *pidx = (chunk_idx * MI_BCHUNK_BITS) + cidx;
1862	          mi_assert_internal(*pidx + n <= mi_bbitmap_max_bits(bbitmap));
1863	          return true;
1864	        }
1865	        else {
1866	          // note: we may find that all are cleared only on a second iteration (when we fail to clear any bits)
1867	          //       but that is ok as the chunkmap is a conservative approximation.
1868	          // todo: should _on_find_ return a boolean if there is a chance all are clear to avoid calling `try_clear?`
1869	          //       probably not as we already only call `try_clear` once we fail to clear any bits.
1870	          if (did_temp_clear_bits) {
1871	            // a concurrent find_and_claim may have cleared the chunkmap bit, restore it now
1872	            mi_bbitmap_chunkmap_set(bbitmap, chunk_idx, false);
1873	          }
1874	          else {
1875	            mi_bbitmap_chunkmap_try_clear(bbitmap, chunk_idx);
1876	          }
1877	        }
1878	      }
1879	      mi_bfield_cycle_iterate_end(Y);
1880	    }
1881	  }
1882	  mi_bfield_cycle_iterate_end(X);
1883	  return false;
1884	}
1885	
1886	/* --------------------------------------------------------------------------------
1887	  mi_bbitmap_try_find_and_clear -- used to find free pages
1888	  note: the compiler will fully inline the indirect function calls
1889	-------------------------------------------------------------------------------- */
1890	
1891	bool mi_bbitmap_try_find_and_clear(mi_bbitmap_t* bbitmap, size_t tseq, size_t* pidx) {
1892	  return mi_bbitmap_try_find_and_clear_generic(bbitmap, tseq, 1, pidx, &mi_bchunk_try_find_and_clear_1);
1893	}
1894	
1895	bool mi_bbitmap_try_find_and_clear8(mi_bbitmap_t* bbitmap, size_t tseq, size_t* pidx) {
1896	  return mi_bbitmap_try_find_and_clear_generic(bbitmap, tseq, 8, pidx, &mi_bchunk_try_find_and_clear_8);
1897	}
1898	
1899	// bool mi_bbitmap_try_find_and_clearX(mi_bbitmap_t* bbitmap, size_t tseq, size_t* pidx) {
1900	//   return mi_bbitmap_try_find_and_clear_generic(bbitmap, tseq, MI_BFIELD_BITS, pidx, &mi_bchunk_try_find_and_clear_X);
1901	// }
1902	
1903	bool mi_bbitmap_try_find_and_clearNX(mi_bbitmap_t* bbitmap, size_t tseq, size_t n, size_t* pidx) {
1904	  mi_assert_internal(n<=MI_BFIELD_BITS);
1905	  return mi_bbitmap_try_find_and_clear_generic(bbitmap, tseq, n, pidx, &mi_bchunk_try_find_and_clearNX);
1906	}
1907	
1908	bool mi_bbitmap_try_find_and_clearNC(mi_bbitmap_t* bbitmap, size_t tseq, size_t n, size_t* pidx) {
1909	  mi_assert_internal(n<=MI_BCHUNK_BITS);
1910	  return mi_bbitmap_try_find_and_clear_generic(bbitmap, tseq, n, pidx, &mi_bchunk_try_find_and_clearNC);
1911	}
1912	
1913	
1914	/* --------------------------------------------------------------------------------
1915	  mi_bbitmap_try_find_and_clear for huge objects spanning multiple chunks
1916	-------------------------------------------------------------------------------- */
1917	
1918	// Try to atomically clear `n` bits starting at `chunk_idx` where `n` can span over multiple chunks
1919	static bool mi_bchunk_try_clearN_(mi_bbitmap_t* bbitmap, size_t chunk_idx, size_t n) {
1920	  mi_assert_internal((chunk_idx * MI_BCHUNK_BITS) + n <= mi_bbitmap_max_bits(bbitmap));
1921	  size_t m = n;      // bits to go
1922	  size_t count = 0;  // chunk count
1923	  while (m > 0) {
1924	    mi_bchunk_t* chunk = &bbitmap->chunks[chunk_idx + count];
1925	    if (!mi_bchunk_try_clearN(chunk, 0, (m > MI_BCHUNK_BITS ? MI_BCHUNK_BITS : m), NULL, NULL)) {
1926	      goto rollback;
1927	    }
1928	    m = (m <= MI_BCHUNK_BITS ? 0 : m - MI_BCHUNK_BITS);
1929	    count++;
1930	  }
1931	  return true;
1932	
1933	rollback:
1934	  // we only need to reset chunks the we just fully cleared
1935	  while (count > 0) {
1936	    count--;
1937	    mi_bchunk_t* chunk = &bbitmap->chunks[chunk_idx + count];
1938	    mi_bchunk_setN(chunk, 0, MI_BCHUNK_BITS, NULL);
1939	    // since we may race with clearing, we need to set the chunkmap conservatively
1940	    mi_bbitmap_chunkmap_set(bbitmap, chunk_idx + count, false);
1941	  }
1942	  return false;
1943	}
1944	
1945	// Go through the bbitmap to find a sequence of `n` bits and clear them atomically where `n > MI_ARENA_MAX_CHUNK_OBJ_SIZE`
1946	// Since these are very large object allocations we always search from the start and only consider starting at the start
1947	// of a chunk (for fragmentation and efficiency).
1948	// Todo: for now we try to find full empty chunks to cover `n` but we can allow a partial chunk at the end
1949	// Todo: This scans directly through the chunks -- we might want to consult the cmap as well?
1950	bool mi_bbitmap_try_find_and_clearN_(mi_bbitmap_t* bbitmap, size_t tseq, size_t n, size_t* pidx) {
1951	  MI_UNUSED(tseq);
1952	  mi_assert(n > 0); if (n==0) { return false; }
1953	
1954	  const size_t chunk_max = mi_bbitmap_chunk_count(bbitmap);
1955	  const size_t chunk_req = _mi_divide_up(n, MI_BCHUNK_BITS);  // minimal number of chunks needed
1956	  if (chunk_max < chunk_req) { return false; }
1957	
1958	  // iterate through the chunks
1959	  size_t chunk_idx = 0;
1960	  while (chunk_idx <= chunk_max - chunk_req)
1961	  {
1962	    size_t count = 0;  // chunk count
1963	    do {
1964	      mi_assert_internal(chunk_idx + count < chunk_max);
1965	      mi_bchunk_t* const chunk = &bbitmap->chunks[chunk_idx + count];
1966	      if (!mi_bchunk_all_are_set_relaxed(chunk)) {
1967	        break;
1968	      }
1969	      else {
1970	        count++;
1971	      }
1972	    }
1973	    while (count < chunk_req);
1974	
1975	    // did we find a suitable range?
1976	    if (count == chunk_req) {
1977	      // now try to claim it!      
1978	      if (mi_bchunk_try_clearN_(bbitmap, chunk_idx, n)) {
1979	        *pidx = (chunk_idx * MI_BCHUNK_BITS);
1980	        for (size_t i = 0; i < count; i++) {
1981	          mi_bbitmap_set_chunk_bin(bbitmap, chunk_idx + i, MI_CBIN_HUGE);
1982	        }
1983	        mi_assert_internal(*pidx + n <= mi_bbitmap_max_bits(bbitmap));
1984	        return true;
1985	      }
1986	      else {
1987	        // contended: we reset count to retry from the first 
1988	        // (we still skip the first chunk to guarantee progress)
1989	        count = 0;
1990	      }
1991	    }
1992	
1993	    // keep searching but skip the scanned range
1994	    chunk_idx += count+1;
1995	  }
1996	  return false;
1997	}
1998	
